for pk,values in edits.items():
 rows=[r for r in cat['records'] if r['scope']=='base' and r['collection']=='candidate_json' and r['field']=='description_as_running_mate' and r['location']['pk']==pk]
 if len(rows)!=1:raise ValueError((pk,len(rows)))
 source=rows[0]['source'];parts=re.split(r'(<[^>]*>)',source)
 indices=[i for i in range(0,len(parts),2) if parts[i].strip()]
